\label{cor:tractable:holant-star}
Suppose the domain size is~$3$ and $a,b,\lambda \in \mathbb{C}$.
Let $f$ be a succinct ternary signature of type $\tau_3$.
Then $\operatorname{Holant}(f)$ is computable in polynomial time when $f$ has one of the following forms:
\begin{enumerate}
 \item $f = \hphantom{3} \lambda \langle 1, 0,  0 \rangle \hphantom{-}
 = \lambda \left[(1,0, 0)^{\otimes 3} + (0, 1,0)^{\otimes 3} + ( 0,0,1)^{\otimes 3}\right]$; \label{case:cor:tractable:holant-star:equality}
 \item $f =           3  \lambda \langle -5, -2, 4 \rangle
 = \lambda \left[(1,-2,-2)^{\otimes 3} + (-2,1,-2)^{\otimes 3} + (-2,-2,1)^{\otimes 3}\right]$; \label{case:cor:tractable:holant-star:-5-24}
 \item $f = \hphantom{3 \lambda} \langle a, b,  a \rangle \hphantom{-}
 = \hphantom{\lambda \big[}\frac{a + 2 b}{3}  (1,1, 1)^{\otimes 3} + \frac{a - b}{3} \left[(1, \omega, \omega^2)^{\otimes 3} + (1, \omega^2, \omega)^{\otimes 3}\right]$, \label{case:cor:tractable:holant-star:aba}
\end{enumerate}
where $\omega$ is a primitive third root of unity.

\label{cor:tractable:100}
Suppose $\kappa \ge 3$ is the domain size and $\lambda \in \mathbb{C}$.
Let $f$ be a succinct ternary signature of type $\tau_3$.
Then $\operatorname{Holant}(f)$ is computable in polynomial time if $f$ has one of the following forms:
\begin{enumerate}
 \item $f = \lambda               \langle 1,0,0 \rangle$; \label{case:cor:tractable:equality:equality}
 \item $f = \lambda T^{\otimes 3} \langle 1,0,0 \rangle = \lambda \kappa \langle \kappa^2 - 6 \kappa + 4, -2 (\kappa - 2), 4 \rangle$, \label{case:cor:tractable:equality:trans}
\end{enumerate}
where $T = \kappa I_\kappa - 2 J_\kappa$.

