\label{thm:interpolation:pervious}
Suppose $\mathcal{F}$ is a set of signatures and $\tau$ is a succinct signature type with length~$3$.
If there exists an infinite sequence of planar $\mathcal{F}$-gates defined by an initial succinct signature $s \in \mathbb{C}^{3 \times 1}$ of type $\tau$
and a recurrence matrix $M \in \mathbb{C}^{3 \times 3}$ with eigenvalues $\alpha$, $\beta$, and $\gamma$ satisfying the following conditions:
\begin{enumerate}
 \item $\det(M) \ne 0$;
 \item $s$ is not orthogonal to any row eigenvector of $M$;
 \item for all $(i,j,k) \in \Z^3 - \{(0,0,0)\}$ with $i+j+k=0$,
 we have $\alpha^i \beta^j \gamma^k \ne 1$;
\end{enumerate}
then
\[
 \operatorname{Pl-Holant}(\mathcal{F} \union \{f\}) \le_T \operatorname{Pl-Holant}(\mathcal{F}),
\]
for any succinct ternary signature $f$ of type $\tau$.

\label{def:interpolation:lattice_condition}
Fix some $\ell \in \N$.
We say that $\lambda_1, \lambda_2, \dotsc, \lambda_\ell \in \mathbb{C} - \{0\}$ satisfy the \emph{lattice condition}
if for all $x \in \Z^\ell - \{\mathbf{0}\}$ with $\sum_{i=1}^\ell x_i = 0$,
we have $\prod_{i=1}^\ell \lambda_i^{x_i} \ne 1$.

\label{lem:interpolation:lattice_condition:cubic}
Let $f(x) \in \Q[x]$ be an irreducible cubic polynomial.
Then the roots of $f(x)$ satisfy the lattice condition iff $f(x)$ is not of the form $a x^3 + b$ for some $a,b \in \Q$.

\begin{equation} \label{eqn:lattice_condition_fails}
  a_1^{x_1} \dotsb a_n^{x_n} = 1.
 \end{equation}

\label{lem:interpolate_all_not_orthogonal}
Suppose $\mathcal{F}$ is a set of signatures and $\tau$ is a succinct signature type with length $n \in \Z^+$.
If there exists an infinite sequence of planar $\mathcal{F}$-gates defined by an initial succinct signature $s \in \mathbb{C}^{n \times 1}$ of type $\tau$
and a recurrence matrix $M \in \mathbb{C}^{n \times n}$ satisfying the following conditions,
\begin{enumerate}
 \item $M$ is diagonalizable with $n$ linearly independent eigenvectors;
 \item $s$ is not orthogonal to exactly $\ell$ of these linearly independent row eigenvectors of $M$ with eigenvalues $\lambda_1, \dotsc, \lambda_\ell$;
 \item $\lambda_1, \dotsc, \lambda_\ell$ satisfy the lattice condition;
\end{enumerate}
then
\[
 \operatorname{Pl-Holant}(\mathcal{F} \union \{f\}) \le_T \operatorname{Pl-Holant}(\mathcal{F})
\]
for any succinct signature $f$ of type $\tau$ that is orthogonal to the $n - \ell$ of these linearly independent eigenvectors of $M$ to which $s$ is also orthogonal.

